// 2. Validate & Clean Input
// Returns { valid: true, ... } for good input, or { valid: false, http_status, error, field }.
const MAX_TEXT = 2000;
const MIN_TEXT = 10;
const MAX_ID = 100;

// Allowed values. Anything else is mapped to "unknown".
const CUSTOMER_TYPES = ['individual', 'household', 'sme', 'corporate', 'enterprise'];
// EDIT THIS LIST if your service_type values differ.
const SERVICE_TYPES = ['postpaid', 'prepaid', 'data', 'voice', 'sms', 'roaming', 'broadband', 'international_calling', 'business_plan', 'add_on_package'];
const SEGMENTS = {
  product_used: ['postpaid_plan', 'data_bundle', 'roaming', 'international_calling', 'business_plan', 'add_on_package'],
  plan_type: ['basic', 'standard', 'premium', 'business'],
  customer_value_segment: ['low', 'medium', 'high', 'premium'],
  usage_behavior: ['high_data_user', 'low_usage_user', 'roaming_user', 'business_critical_user', 'price_sensitive_user'],
  business_individual_segment: ['individual', 'business'],
  tenure_segment: ['new_customer', 'existing_customer', 'long_term_customer'],
};

// Emails: anything that looks like name@domain.tld
const EMAIL_REGEX = /[^\s@<>()\[\]",;]+@[^\s@<>()\[\]",;]+\.[^\s@<>()\[\]",;]+/g;
// Pakistani mobiles: +92 300 1234567, 0092-300-1234567, 0300-1234567, 03001234567, 923001234567,
// with optional spaces, dashes, dots or brackets around the operator code.
const PAK_PHONE_REGEX = /(?<!\d)(?:(?:\+|00)?92[\s\-.]?|0)\(?3\d{2}\)?[\s\-.]?\d{3}[\s\-.]?\d{4}(?!\d)/g;

const urgencyPatterns = [
  { pattern: /\bcancel\w*/i, label: 'cancel' },
  { pattern: /\bswitch\w*/i, label: 'switch' },
  { pattern: /\boutage\w*/i, label: 'outage' },
  { pattern: /\bfraud\w*/i, label: 'fraud' },
  { pattern: /\b(legal\w*|lawsuit|court\s?case|sue\b|suing\b)/i, label: 'legal' },
  { pattern: /\brefund\w*/i, label: 'refund' },
  { pattern: /\bterminat\w*/i, label: 'terminate' },
  { pattern: /\bdisconnect\w*/i, label: 'disconnect' },
  { pattern: /\b(complain\w*|escalat\w*|PTA\b|PEMRA\b|regulator\w*)/i, label: 'complaint_escalation' },
  { pattern: /\b(band\s?karo|chorr?\w*|chorna|chod\w*|nikal\w*|wapas\w*|dobara\s?nahi|nahi\s?chahiye|problem\s?hai|bahut\s?bura)\b/i, label: 'roman_urdu_urgency' },
  { pattern: /\b(jazz|telenor|zong|ufone|going\s?to\s?(switch|leave|move))\b/i, label: 'competitor_switch' },
  { pattern: /\b(leaving|leaving\s?orbitel|port\s?out|number\s?portability|MNP)\b/i, label: 'leaving' },
];

function fail(status, error, field) {
  return [{ json: { valid: false, http_status: status, error: error, field: field || null } }];
}

// Collapse every run of whitespace/control characters (newline, tab, CR...) to one space.
function oneLine(s) {
  return String(s).replace(/[\s\u0000-\u001f\u007f]+/g, ' ').trim();
}

function pickEnum(v, allowed) {
  if (typeof v !== 'string') return 'unknown';
  const key = v.trim().toLowerCase().replace(/[\s\-]+/g, '_');
  return allowed.includes(key) ? key : 'unknown';
}

function freeText(v, max) {
  if (typeof v === 'number' && Number.isFinite(v)) v = String(v);
  if (typeof v !== 'string') return 'unknown';
  const s = oneLine(v);
  if (s === '') return 'unknown';
  return Array.from(s).slice(0, max).join('');
}

function makeRecordId() {
  let u = '';
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') u = crypto.randomUUID();
  } catch (e) { u = ''; }
  if (!u) {
    u = Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 6);
  }
  return 'rec-' + Date.now().toString(36) + '-' + u;
}

try {
  const input = $input.first().json || {};
  const headers = input.headers || {};
  const contentType = String(headers['content-type'] || '').toLowerCase();
  const body = input.body;

  if (!contentType.includes('json')) {
    return fail(400, 'Request must be sent as JSON with Content-Type: application/json.', 'body');
  }
  if (body === undefined || body === null || typeof body !== 'object' || Array.isArray(body)) {
    return fail(400, 'Request body must be a JSON object.', 'body');
  }

  // ---- text
  const rawText = body.text;
  if (rawText === undefined || rawText === null) return fail(400, 'text is required.', 'text');
  if (typeof rawText !== 'string') return fail(400, 'text must be a string.', 'text');
  let text = oneLine(rawText);
  if (Array.from(text).length < MIN_TEXT) {
    return fail(400, 'text must be at least ' + MIN_TEXT + ' characters after trimming.', 'text');
  }

  // ---- customer_id
  let customerId = body.customer_id;
  if (customerId === undefined || customerId === null) return fail(400, 'customer_id is required.', 'customer_id');
  if (typeof customerId === 'number') {
    if (!Number.isFinite(customerId)) return fail(400, 'customer_id must be a valid number or string.', 'customer_id');
    customerId = String(customerId);
  } else if (typeof customerId === 'string') {
    customerId = oneLine(customerId);
  } else {
    return fail(400, 'customer_id must be a string or a number.', 'customer_id');
  }
  if (customerId === '') return fail(400, 'customer_id must not be empty.', 'customer_id');
  if (Array.from(customerId).length > MAX_ID) {
    return fail(400, 'customer_id must be at most ' + MAX_ID + ' characters.', 'customer_id');
  }

  // ---- redact PII BEFORE anything else sees the text
  text = text.replace(EMAIL_REGEX, '[EMAIL_REMOVED]').replace(PAK_PHONE_REGEX, '[PHONE_REMOVED]');

  // ---- urgency regexes run on the full (redacted) text, before truncation
  let urgency_override = false;
  const matched_urgency_labels = [];
  for (const item of urgencyPatterns) {
    if (item.pattern.test(text)) {
      urgency_override = true;
      matched_urgency_labels.push(item.label);
    }
  }

  // ---- truncate (by code point so emoji are never split)
  let truncated = false;
  const chars = Array.from(text);
  if (chars.length > MAX_TEXT) {
    text = chars.slice(0, MAX_TEXT).join('');
    truncated = true;
  }

  // ---- timestamp
  let timestamp = '';
  const rawTs = body.timestamp;
  if (typeof rawTs === 'string' && rawTs.trim() !== '') {
    const t = rawTs.trim();
    const d = new Date(t);
    if (!isNaN(d.getTime())) {
      timestamp = /^\d{4}-\d{2}-\d{2}T/.test(t) ? t : d.toISOString();
    }
  } else if (typeof rawTs === 'number' && Number.isFinite(rawTs)) {
    const d = new Date(rawTs);
    if (!isNaN(d.getTime())) timestamp = d.toISOString();
  }
  if (!timestamp) timestamp = new Date().toISOString();

  return [{
    json: {
      valid: true,
      http_status: 200,
      customer_id: customerId,
      customer_type: pickEnum(body.customer_type, CUSTOMER_TYPES),
      service_type: pickEnum(body.service_type, SERVICE_TYPES),
      source: freeText(body.source, 100),
      timestamp: timestamp,
      cleanedText: text,
      truncated: truncated,
      urgency_override: urgency_override,
      matched_urgency_labels: matched_urgency_labels,
      record_id: makeRecordId(),
      product_used: pickEnum(body.product_used, SEGMENTS.product_used),
      plan_type: pickEnum(body.plan_type, SEGMENTS.plan_type),
      customer_value_segment: pickEnum(body.customer_value_segment, SEGMENTS.customer_value_segment),
      usage_behavior: pickEnum(body.usage_behavior, SEGMENTS.usage_behavior),
      business_individual_segment: pickEnum(body.business_individual_segment, SEGMENTS.business_individual_segment),
      tenure_segment: pickEnum(body.tenure_segment, SEGMENTS.tenure_segment),
    },
  }];
} catch (e) {
  return fail(500, 'Internal error while validating the request.', null);
}

// 4. Parse AI Response
// Never throws: a bad or missing AI reply becomes a flagged record that is still logged.
const base = $('2. Validate & Clean Input').first().json;
const items = $input.all();
const ai = items.length > 0 ? (items[0].json || {}) : null;

const SENTIMENTS = ['positive', 'negative', 'neutral'];
const CATEGORIES = ['network', 'billing', 'pricing', 'service_delay', 'product_dissatisfaction', 'coverage', 'roaming', 'customer_service'];
const URGENCIES = ['low', 'medium', 'high'];
const DEPARTMENTS = ['operations', 'finance', 'sales', 'marketing', 'hr'];
const SIGNALS = ['coverage_expansion', 'billing_issue', 'upsell_opportunity', 'service_recovery', 'hr_escalation', 'product_feedback', 'none'];
const PRIORITIES = ['immediate', 'within_24h', 'within_week', 'no_action'];
const OFFERS = ['discount', 'bonus_data', 'free_month', 'plan_upgrade', 'service_credit', 'none'];

// Single line, trimmed, length-limited. null/undefined/objects become "".
function oneLine(v, max) {
  let s = '';
  if (typeof v === 'string') s = v;
  else if (typeof v === 'number' || typeof v === 'boolean') s = String(v);
  s = s.replace(/\s+/g, ' ').trim();
  const chars = Array.from(s);
  return chars.length > max ? chars.slice(0, max).join('') : s;
}

function pick(v, allowed, fallback) {
  if (typeof v !== 'string') return fallback;
  const key = v.trim().toLowerCase();
  return allowed.includes(key) ? key : fallback;
}

// Find the first {...} block that parses as a JSON object (ignores prose and code fences).
function parseFirstJsonObject(text) {
  let from = 0;
  for (let attempt = 0; attempt < 20; attempt++) {
    const start = text.indexOf('{', from);
    if (start < 0) return null;
    let depth = 0, inStr = false, esc = false, end = -1;
    for (let i = start; i < text.length; i++) {
      const ch = text[i];
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
        continue;
      }
      if (ch === '"') { inStr = true; continue; }
      if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) { end = i; break; }
      }
    }
    if (end > 0) {
      try {
        const obj = JSON.parse(text.slice(start, end + 1));
        if (obj && typeof obj === 'object' && !Array.isArray(obj)) return obj;
      } catch (e) { /* try the next '{' */ }
    }
    from = start + 1;
  }
  return null;
}

let aiStatus = 'ok';
let parsed = null;

try {
  if (ai === null || ai.error) {
    aiStatus = 'failed';
  } else {
    let text = '';
    const out = ai.output;
    if (Array.isArray(out)) {
      for (const o of out) {
        if (o && Array.isArray(o.content)) {
          for (const c of o.content) {
            if (c && typeof c.text === 'string') text += c.text + '\n';
          }
        }
      }
    }
    if (text.trim() === '' && typeof ai.output_text === 'string') text = ai.output_text;
    text = text.replace(/```(?:json)?/gi, '');
    parsed = text.trim() === '' ? null : parseFirstJsonObject(text);
    if (parsed === null) aiStatus = 'parse_error';
  }
} catch (e) {
  parsed = null;
  aiStatus = 'parse_error';
}

const failed = parsed === null;
const p = failed ? {} : parsed;
const profile = (p.customer_segment_profile && typeof p.customer_segment_profile === 'object') ? p.customer_segment_profile : {};
const tmpl = (p.retention_template && typeof p.retention_template === 'object') ? p.retention_template : {};

// sentiment
const sentiment = pick(p.sentiment, SENTIMENTS, 'neutral');

// confidence_score: number clamped to 0..1, else 0
let confidence = 0;
let n = NaN;
if (typeof p.confidence_score === 'number') n = p.confidence_score;
else if (typeof p.confidence_score === 'string' && p.confidence_score.trim() !== '') n = Number(p.confidence_score);
if (Number.isFinite(n)) confidence = Math.round(Math.min(1, Math.max(0, n)) * 1000) / 1000;

// issue_categories: allowed values only, joined into a clean string
let cats = [];
if (Array.isArray(p.issue_categories)) {
  cats = p.issue_categories
    .map((c) => (typeof c === 'string' ? c.trim().toLowerCase() : ''))
    .filter((c) => CATEGORIES.includes(c));
  cats = Array.from(new Set(cats));
}

// urgency: validate, then apply the regex override. A failed analysis is always "high" for human review.
let urgency = pick(p.urgency, URGENCIES, 'medium');
if (base.urgency_override === true) urgency = 'high';
if (failed) urgency = 'high';

// churn_risk: real boolean only
let churn = false;
if (p.churn_risk === true) churn = true;
else if (typeof p.churn_risk === 'string' && p.churn_risk.trim().toLowerCase() === 'true') churn = true;

// retention
let priority = pick(tmpl.priority, PRIORITIES, 'no_action');
if (churn) priority = 'immediate';
const offerType = pick(tmpl.offer_type, OFFERS, 'none');

// location: never the text "null"
let location = oneLine(p.location_mentioned, 80);
if (location.toLowerCase() === 'null') location = '';

let rootCause = oneLine(p.root_cause_summary, 1000);
let action = oneLine(p.recommended_action, 1000);
if (failed) {
  rootCause = 'AI analysis unavailable (' + aiStatus + '). Manual review of the original feedback is required.';
  action = 'Manual review: read the original feedback and route it to the right department.';
}

const segmentImpact = oneLine(profile.segment_interpretation, 500) || oneLine(p.customer_segment_impact, 500) || 'unknown';

return [{
  json: {
    customer_id: base.customer_id,
    customer_type: base.customer_type,
    service_type: base.service_type,
    record_id: base.record_id,
    source: base.source,
    timestamp: base.timestamp,
    original_text: base.cleanedText,
    truncated: base.truncated === true,

    sentiment: sentiment,
    confidence_score: confidence,
    issue_categories: cats.join(', '),
    urgency: urgency,
    churn_risk: churn,
    root_cause_summary: rootCause,
    recommended_action: action,

    business_signal: pick(p.business_signal, SIGNALS, 'none'),
    customer_segment_impact: segmentImpact,
    target_department: pick(p.target_department, DEPARTMENTS, 'operations'),
    location_mentioned: location,

    retention_offer_type: offerType,
    retention_message: oneLine(tmpl.message_draft, 1000),
    retention_priority: priority,

    // Segmentation comes from the request (node 2), never from model guesses.
    product_used: base.product_used,
    plan_type: base.plan_type,
    customer_value_segment: base.customer_value_segment,
    usage_behavior: base.usage_behavior,
    business_individual_segment: base.business_individual_segment,
    tenure_segment: base.tenure_segment,

    matched_urgency_labels: (base.matched_urgency_labels || []).join(', '),
    parse_error: aiStatus === 'parse_error',
    ai_status: aiStatus,
    status: failed ? 'error' : 'ok',
  },
}];

// 9. Dedup Check (per customer, window depends on business_signal)
const current = $('4. Parse AI Response').first().json;

const WINDOWS = {
  coverage_expansion: 7 * 24,   // 7 days
  billing_issue: 30 * 24,       // 30 days
  service_recovery: 48,         // 48 hours
  hr_escalation: 7 * 24,        // 7 days
  upsell_opportunity: 30 * 24,  // 30 days
  product_feedback: 90 * 24,    // 90 days
  none: 24,                     // 24 hours
};
const windowHours = WINDOWS[current.business_signal] || 24;

const now = new Date();
const windowStart = now.getTime() - windowHours * 60 * 60 * 1000;
const upperBound = now.getTime() + 5 * 60 * 1000; // small allowance for clock skew

let rows = [];
try {
  rows = $input.all().map((i) => i.json || {});
} catch (e) {
  rows = [];
}

const isTrue = (v) => String(v).trim().toLowerCase() === 'true';
const sameText = (a, b) => String(a === undefined || a === null ? '' : a).trim() === String(b === undefined || b === null ? '' : b).trim();

let duplicate = null;
let duplicateTime = 0;

// A record whose AI analysis failed is never treated as a duplicate: a human must see it.
if (current.ai_status === 'ok') {
  for (const row of rows) {
    if (!row || row.error) continue;                          // failed/empty lookup
    if (!row.record_id || !row.timestamp || !row.business_signal) continue;
    if (!sameText(row.customer_id, current.customer_id)) continue;
    if (!sameText(row.business_signal, current.business_signal)) continue;
    if (sameText(row.record_id, current.record_id)) continue;  // ignore itself (retries)
    // Only compare against rows that were real analyses and not themselves suppressed duplicates
    if (isTrue(row.is_duplicate) || isTrue(row.parse_error)) continue;
    if (row.ai_status && String(row.ai_status).trim() !== 'ok') continue;
    const t = new Date(row.timestamp).getTime();
    if (isNaN(t)) continue;                                    // unparseable timestamp
    if (t >= windowStart && t <= upperBound && t >= duplicateTime) {
      duplicate = row;
      duplicateTime = t;
    }
  }
}

return [{
  json: {
    ...current,
    is_duplicate: duplicate !== null,
    duplicate_of: duplicate !== null ? String(duplicate.record_id) : '',
    dedup_window_hours: windowHours,
    past_rows_count: rows.filter((r) => r && r.record_id).length,
    dedup_check_time: now.toISOString(),
  },
}];

// 10a. Prepare Alert Fields
// The Sheets node returns only the written row, so read the full record from node 9.
// Everything printed into the HTML email is escaped here.
const rec = $('9. Dedup Check').first().json;

function esc(v) {
  return String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
function plain(v, max) {
  const s = String(v === null || v === undefined ? '' : v).replace(/[\s\u0000-\u001f\u007f]+/g, ' ').trim();
  return Array.from(s).slice(0, max).join('');
}

const manual = rec.ai_status !== 'ok';
const banner = manual
  ? '<p style="background: #fdecea; color: #c0392b; padding: 10px; border-left: 4px solid #c0392b;"><strong>Manual review required:</strong> the AI analysis was unavailable or unreadable for this record (ai_status: ' + esc(rec.ai_status) + '). The analysis fields below are defaults.</p>'
  : '';

return [{
  json: {
    customer_id: esc(rec.customer_id),
    record_id: esc(rec.record_id),
    source: esc(rec.source),
    location_mentioned: esc(rec.location_mentioned),
    issue_categories: esc(rec.issue_categories),
    business_signal: esc(rec.business_signal),
    urgency: esc(rec.urgency),
    churn_risk: esc(rec.churn_risk),
    sentiment: esc(rec.sentiment),
    root_cause_summary: esc(rec.root_cause_summary),
    retention_offer_type: esc(rec.retention_offer_type),
    retention_priority: esc(rec.retention_priority),
    retention_message: esc(rec.retention_message),
    original_text: esc(rec.original_text),
    dedup_check_time: esc(rec.dedup_check_time),
    dedup_window_hours: esc(rec.dedup_window_hours),
    target_department: rec.target_department,
    review_banner: banner,
    // Plain-text values for email subjects (single line, no feedback text)
    subject_customer: plain(rec.customer_id, 60),
    subject_location: plain(rec.location_mentioned, 60),
  },
}];
